public class JsonReader_nextInt_TriageGen1Test {

    @Test
    public void test_peakedIsPEEKED_NONE_DoPeekReturnsPEEKED_LONG() throws IOException {
        JsonReader jsonReader = new JsonReader(new StringReader("123"));
        jsonReader.peeked = JsonReader.PEEKED_NONE;
        jsonReader.doPeek = () -> JsonReader.PEEKED_LONG;
        jsonReader.peekedLong = 123;
        assertEquals(123, jsonReader.nextInt());
    }

    @Test
    public void test_peakedIsPEEKED_NONE_DoPeekReturnsPEEKED_NUMBER() throws IOException {
        JsonReader jsonReader = new JsonReader(new StringReader("123"));
        jsonReader.peeked = JsonReader.PEEKED_NONE;
        jsonReader.doPeek = () -> JsonReader.PEEKED_NUMBER;
        jsonReader.peekedNumberLength = 3;
        jsonReader.buffer = new byte[]{'1', '2', '3'};
        jsonReader.pos = 0;
        assertEquals(123, jsonReader.nextInt());
    }

    @Test
    public void test_peakedIsPEEKED_NONE_DoPeekReturnsPEEKED_SINGLE_QUOTED() throws IOException {
        JsonReader jsonReader = new JsonReader(new StringReader("'123'"));
        jsonReader.peeked = JsonReader.PEEKED_NONE;
        jsonReader.doPeek = () -> JsonReader.PEEKED_SINGLE_QUOTED;
        jsonReader.peekedString = "'123'";
        assertEquals(123, jsonReader.nextInt());
    }

    @Test
    public void test_peakedIsPEEKED_NONE_DoPeekReturnsPEEKED_DOUBLE_QUOTED() throws IOException {
